def pytest_generate_tests(metafunc):
    """Generate tests."""
    if os.path.isdir(CODE_DIRECTORY):
        os.system(f"rm {CODE_DIRECTORY}/*.c")
        os.system(f"rm {CODE_DIRECTORY}/*.o")
        os.system(f"rm {CODE_DIRECTORY}/*.so")
    else:
        os.mkdir(CODE_DIRECTORY)
